package com.fandazi.feature.order;
import com.fandazi.feature.delivery.DeliveryService; import com.fandazi.feature.payment.PaymentService; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController { private final OrderService orders; private final PaymentService payments; public OrderController(OrderService orders,PaymentService payments){this.orders=orders;this.payments=payments;} public record CreateRequest(Long cartDraftId,Long addressId){} @PostMapping public ResponseEntity<OrderResponse> create(@AuthenticationPrincipal Long userId,@RequestHeader("Idempotency-Key") String key,@RequestBody CreateRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(OrderResponse.from(orders.create(userId,new CreateOrderCommand(request.cartDraftId(),request.addressId(),key))));}@PostMapping("/{id}/pay") public OrderResponse pay(@AuthenticationPrincipal Long userId,@PathVariable Long id,@RequestHeader("Idempotency-Key") String key){return OrderResponse.from(payments.pay(userId,id,key));}@GetMapping("/{id}") public OrderResponse get(@AuthenticationPrincipal Long userId,@PathVariable Long id){return OrderResponse.from(orders.get(userId,id));} }
